      /* HERO RIGHT COLUMN: MASSIVE, SLEEK CAR DISPLAY */
      .header__image-col {
        position: relative;
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: center;
      }

      .header__image-wrapper {
        position: relative;
        width: 100%;
        min-height: 460px;
        display: flex;
        align-items: center;
        justify-content: center;
      }

      .hero-bg-card {
        position: absolute;
        top: 15px;
        right: 0;
        bottom: 15px;
        left: 20px;
        background: linear-gradient(135deg, rgba(99, 102, 241, 0.12) 0%, rgba(168, 85, 247, 0.1) 55%, rgba(244, 114, 182, 0.08) 100%);
        border-radius: 2.75rem;
        border: 1px solid rgba(226, 232, 240, 0.95);
        box-shadow: 0 25px 45px -15px rgba(79, 70, 229, 0.12);
        z-index: 0;
      }

      .hero-bg-glow {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 420px;
        height: 420px;
        background: radial-gradient(circle, rgba(99, 102, 241, 0.28) 0%, rgba(147, 51, 234, 0.12) 50%, transparent 70%);
        filter: blur(45px);
        pointer-events: none;
        z-index: 0;
      }

      .hero-main-car {
        position: relative !important;
        z-index: 2 !important;
        width: 122% !important;
        max-width: 680px !important;
        height: auto !important;
        object-fit: contain !important;
        transform: scale(1.12) translateX(2%) !important;
        filter: drop-shadow(0 24px 30px rgba(15, 23, 42, 0.35)) !important;
        transition: transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
        pointer-events: auto;
      }

      .header__image-wrapper:hover .hero-main-car {
        transform: scale(1.18) translateY(-6px) translateX(2%) !important;
        filter: drop-shadow(0 32px 42px rgba(15, 23, 42, 0.45)) !important;
      }

      .hero-ground-shadow {
        position: absolute;
        bottom: 18px;
        left: 50%;
        transform: translateX(-47%);
        width: 88%;
        max-width: 620px;
        height: 32px;
        background: radial-gradient(ellipse at center, rgba(15, 23, 42, 0.45) 0%, rgba(15, 23, 42, 0.15) 50%, transparent 75%);
        border-radius: 50%;
        filter: blur(7px);
        z-index: 1;
        pointer-events: none;
      }

      .hero-floating-card {
        position: absolute !important;
        z-index: 4 !important;
        background: rgba(255, 255, 255, 0.94) !important;
        backdrop-filter: blur(14px) !important;
        -webkit-backdrop-filter: blur(14px) !important;
        padding: 12px 18px !important;
        border-radius: 18px !important;
        display: flex !important;
        align-items: center !important;
        gap: 12px !important;
        box-shadow: 0 16px 32px -8px rgba(15, 23, 42, 0.12), 0 0 0 1px rgba(255, 255, 255, 0.9) inset !important;
        border: 1px solid rgba(226, 232, 240, 0.8) !important;
        animation: floatSlow 4.5s ease-in-out infinite alternate !important;
      }

      .hero-floating-top {
        top: 20px !important;
        left: -10px !important;
      }

      .hero-floating-bottom {
        bottom: 25px !important;
        right: -15px !important;
        animation-delay: -2.25s !important;
      }

      .floating-icon {
        width: 40px;
        height: 40px;
        border-radius: 12px;
        background: rgba(79, 70, 229, 0.1);
        color: #4f46e5;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 1.3rem;
      }

      .floating-icon.promo {
        background: rgba(249, 115, 22, 0.1);
        color: #f97316;
      }

      @keyframes floatSlow {
        0% { transform: translateY(0px); }
        100% { transform: translateY(-9px); }
      }

      /* SEARCH FORM - MODERN FLOATING CARD */
      .header__form {
        max-width: 1200px !important;
        margin: -3.5rem auto 4rem auto !important;
        position: relative !important;
        z-index: 10 !important;
        padding: 0 1.5rem !important;
      }

      .header__form form {
        background: rgba(255, 255, 255, 0.98) !important;
        backdrop-filter: blur(20px) !important;
        -webkit-backdrop-filter: blur(20px) !important;
        border: 1px solid rgba(226, 232, 240, 0.9) !important;
        box-shadow: 0 25px 50px -12px rgba(15, 23, 42, 0.14) !important;
        border-radius: 24px !important;
        padding: 1.75rem 2.25rem !important;
        display: grid !important;
        grid-template-columns: 1.3fr 1fr 1fr auto !important;
        align-items: flex-end !important;
        gap: 1.5rem !important;
      }

      .header__form .input__group label {
        display: flex !important;
        align-items: center !important;
        gap: 8px !important;
        font-size: 0.88rem !important;
        font-weight: 700 !important;
        color: #334155 !important;
        margin-bottom: 0.5rem !important;
      }

      .header__form input {
        width: 100% !important;
        padding: 14px 16px !important;
        font-size: 0.95rem !important;
        font-family: inherit !important;
        border: 1.5px solid #e2e8f0 !important;
        border-radius: 14px !important;
        background: #f8fafc !important;
        color: #0f172a !important;
        outline: none !important;
        transition: all 0.25s ease !important;
        box-sizing: border-box !important;
      }

      .header__form input:focus {
        border-color: #4f46e5 !important;
        background: #ffffff !important;
        box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12) !important;
      }

      .btn-search-primary {
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        color: #ffffff !important;
        font-weight: 700 !important;
        font-size: 1rem !important;
        padding: 15px 32px !important;
        border-radius: 14px !important;
        border: none !important;
        cursor: pointer !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        gap: 10px !important;
        height: 52px !important;
        box-shadow: 0 10px 22px -5px rgba(79, 70, 229, 0.5) !important;
        transition: all 0.25s ease !important;
        white-space: nowrap !important;
      }

      .btn-search-primary:hover {
        transform: translateY(-2px) !important;
        box-shadow: 0 16px 30px -5px rgba(79, 70, 229, 0.65) !important;
      }

      @media (max-width: 1080px) {
        .header__container {
          grid-template-columns: 1fr !important;
          gap: 3.5rem !important;
          padding-bottom: 4rem !important;
        }
        .header__image-wrapper {
          min-height: 380px !important;
        }
        .hero-main-car {
          width: 100% !important;
          transform: scale(1.08) !important;
        }
        .header__form form {
          grid-template-columns: 1fr 1fr !important;
        }
        .search-btn-wrapper {
          grid-column: span 2 !important;
        }
        .btn-search-primary {
          width: 100% !important;
        }
      }

      @media (max-width: 768px) {
        .nav__inner {
          padding: 0.75rem 1rem !important;
        }
        .nav__links {
          display: none !important;
        }
        .nav__menu__btn {
          display: block !important;
        }
        .hero-title {
          font-size: 2.75rem !important;
        }
        .header__form form {
          grid-template-columns: 1fr !important;
          padding: 1.5rem !important;
        }
        .search-btn-wrapper {
          grid-column: span 1 !important;
        }
        .hero-floating-card {
          padding: 8px 12px !important;
          font-size: 0.8rem !important;
        }
      }
  
    

      /* =========================================================
         GLOBAL UNIFIED TYPOGRAPHY (ALL FONTS SAME)
         ========================================================= */
      /* Unified Font without breaking icon fonts */
      html, body, button, input, select, textarea, optgroup,
      h1, h2, h3, h4, h5, h6, p, a, strong, em, label {
        font-family: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif !important;
      }
      
      /* Bulletproof RemixIcon restoration */
      i[class*="ri-"], [class^="ri-"], [class*=" ri-"],
      i[class*="ri-"]::before, [class^="ri-"]::before, [class*=" ri-"]::before {
        font-family: 'remixicon' !important;
        font-style: normal !important;
        -webkit-font-smoothing: antialiased !important;
      }
  

