      /* Profile Chip inside nav */
      .profile-container {
        position: relative !important;
        display: inline-block !important;
      }

      .profile-chip {
        display: inline-flex !important;
        align-items: center !important;
        gap: 8px !important;
        padding: 8px 18px !important;
        background: #0f172a !important;
        border-radius: 50px !important;
        color: #ffffff !important;
        font-size: 0.9rem !important;
        font-weight: 700 !important;
        cursor: pointer !important;
        transition: all 0.2s ease !important;
        border: 1px solid #0f172a !important;
        box-shadow: 0 4px 12px rgba(15, 23, 42, 0.15) !important;
      }

      .profile-chip:hover {
        background: #334155 !important;
      }

      .profile-avatar {
        width: 26px !important;
        height: 26px !important;
        border-radius: 50% !important;
        background: rgba(255, 255, 255, 0.2) !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        font-size: 0.85rem !important;
      }

      .profile-dropdown {
        position: absolute !important;
        top: calc(100% + 12px) !important;
        right: 0 !important;
        width: 260px !important;
        background: #ffffff !important;
        border-radius: 16px !important;
        box-shadow: 0 20px 40px rgba(15, 23, 42, 0.18) !important;
        border: 1px solid #e2e8f0 !important;
        padding: 1rem !important;
        display: none !important;
        z-index: 10000 !important;
      }

      .profile-dropdown.show {
        display: block !important;
        animation: fadeInDown 0.25s ease forwards !important;
      }

      @keyframes fadeInDown {
        from { opacity: 0; transform: translateY(-8px); }
        to { opacity: 1; transform: translateY(0); }
      }

      /* CRUCIAL: HAMBURGER BUTTON IS HIDDEN ON DESKTOP */
      .nav__menu__btn {
        display: none !important;
        font-size: 1.6rem !important;
        color: #0f172a !important;
        cursor: pointer !important;
      }

      @media (max-width: 868px) {
        .nav__menu__btn {
          display: block !important;
        }
        .nav__links {
          display: none !important;
        }
        .nav__links.open {
          display: flex !important;
          flex-direction: column !important;
          position: absolute !important;
          top: 100% !important;
          left: 0 !important;
          right: 0 !important;
          background: #ffffff !important;
          padding: 1.5rem !important;
          box-shadow: 0 10px 25px rgba(0,0,0,0.1) !important;
          gap: 1rem !important;
        }
      }
  

      /* =========================================================
         TESTIMONIALS SECTION - CLEAN 64PX CIRCULAR AVATARS
         ========================================================= */
      .client__container {
        padding-block: 5rem !important;
        max-width: 1280px !important;
        margin: 0 auto !important;
        padding-inline: 1.5rem !important;
      }

      .client__card {
        background: #ffffff !important;
        border: 1px solid #e2e8f0 !important;
        border-radius: 20px !important;
        padding: 2rem !important;
        box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.05) !important;
        display: flex !important;
        flex-direction: column !important;
        justify-content: space-between !important;
        height: 100% !important;
        min-height: 220px !important;
        transition: all 0.3s ease !important;
        box-sizing: border-box !important;
      }

      .client__card:hover {
        transform: translateY(-5px) !important;
        box-shadow: 0 20px 35px -5px rgba(79, 70, 229, 0.12) !important;
        border-color: rgba(79, 70, 229, 0.3) !important;
      }

      .client__details {
        display: flex !important;
        align-items: center !important;
        gap: 1rem !important;
        margin-bottom: 1.25rem !important;
      }

      .client__details img {
        width: 64px !important;
        height: 64px !important;
        max-width: 64px !important;
        max-height: 64px !important;
        min-width: 64px !important;
        min-height: 64px !important;
        border-radius: 50% !important;
        object-fit: cover !important;
        border: 3px solid #4f46e5 !important;
        box-shadow: 0 4px 12px rgba(79, 70, 229, 0.25) !important;
        flex-shrink: 0 !important;
        display: block !important;
      }

      .client__details h4 {
        font-size: 1.1rem !important;
        font-weight: 700 !important;
        color: #0f172a !important;
        margin-bottom: 0.25rem !important;
      }

      .client__rating {
        color: #f59e0b !important;
        font-size: 0.95rem !important;
        display: flex !important;
        gap: 2px !important;
      }

      .client__card p {
        font-size: 0.98rem !important;
        line-height: 1.65 !important;
        color: #475569 !important;
        font-style: italic !important;
        margin: 0 !important;
      }
  

      /* =========================================================
         FOOTER: 4-COLUMN FULL LINE SLEEK SAAS FOOTER
         ========================================================= */
      .footer {
        background: #0b1120 !important;
        color: #94a3b8 !important;
        padding-top: 5rem !important;
        padding-bottom: 2.5rem !important;
        width: 100% !important;
        margin-top: 5rem !important;
        border-top: 1px solid rgba(255, 255, 255, 0.08) !important;
      }

      .footer__container {
        max-width: 1320px !important;
        margin: 0 auto !important;
        padding: 0 2rem 4rem 2rem !important;
        display: grid !important;
        grid-template-columns: 1.4fr 1fr 1fr 1.2fr !important;
        gap: 3.5rem !important;
        box-sizing: border-box !important;
      }

      .footer__col h4 {
        color: #ffffff !important;
        font-size: 1.15rem !important;
        font-weight: 800 !important;
        letter-spacing: -0.02em !important;
        margin-bottom: 1.5rem !important;
        position: relative !important;
      }

      .footer__col h4::after {
        content: "" !important;
        position: absolute !important;
        left: 0 !important;
        bottom: -6px !important;
        width: 32px !important;
        height: 3px !important;
        background: linear-gradient(90deg, #4f46e5, #9333ea) !important;
        border-radius: 2px !important;
      }

      .footer__logo {
        margin-bottom: 1.25rem !important;
      }

      .footer__logo .logo {
        display: inline-flex !important;
        align-items: center !important;
        gap: 10px !important;
        text-decoration: none !important;
      }

      .footer__logo .logo span {
        font-size: 1.5rem !important;
        font-weight: 900 !important;
        color: #ffffff !important;
      }

      .footer__logo .logo span span {
        color: #818cf8 !important;
      }

      .footer__col p {
        color: #94a3b8 !important;
        font-size: 0.95rem !important;
        line-height: 1.7 !important;
        margin-bottom: 1.5rem !important;
      }

      .footer__socials {
        display: flex !important;
        align-items: center !important;
        gap: 12px !important;
        list-style: none !important;
        padding: 0 !important;
        margin: 0 !important;
      }

      .footer__socials a {
        width: 40px !important;
        height: 40px !important;
        border-radius: 10px !important;
        background: rgba(255, 255, 255, 0.06) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        color: #ffffff !important;
        font-size: 1.15rem !important;
        transition: all 0.3s ease !important;
        text-decoration: none !important;
      }

      .footer__socials a:hover {
        background: #4f46e5 !important;
        border-color: #4f46e5 !important;
        transform: translateY(-3px) !important;
        box-shadow: 0 8px 18px rgba(79, 70, 229, 0.4) !important;
      }

      .footer__links {
        list-style: none !important;
        padding: 0 !important;
        margin: 0 !important;
        display: flex !important;
        flex-direction: column !important;
        gap: 12px !important;
      }

      .footer__links a {
        color: #94a3b8 !important;
        font-size: 0.95rem !important;
        text-decoration: none !important;
        display: inline-flex !important;
        align-items: center !important;
        gap: 8px !important;
        transition: all 0.2s ease !important;
      }

      .footer__links a:hover {
        color: #ffffff !important;
        transform: translateX(4px) !important;
      }

      .footer__links a span {
        color: #818cf8 !important;
        font-size: 1.1rem !important;
      }

      .footer__bar {
        max-width: 1320px !important;
        margin: 0 auto !important;
        padding: 2rem 2rem 0 2rem !important;
        border-top: 1px solid rgba(255, 255, 255, 0.06) !important;
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        color: #64748b !important;
        font-size: 0.88rem !important;
        flex-wrap: wrap !important;
        gap: 1rem !important;
      }

      .footer__bar a {
        color: #94a3b8 !important;
        text-decoration: none !important;
        margin-left: 1.5rem !important;
      }

      .footer__bar a:hover {
        color: #ffffff !important;
      }

      @media (max-width: 1024px) {
        .footer__container {
          grid-template-columns: repeat(2, 1fr) !important;
          gap: 3rem !important;
        }
      }

      @media (max-width: 640px) {
        .footer__container {
          grid-template-columns: 1fr !important;
          gap: 2.5rem !important;
        }
      }
  

    
      /* =========================================================
         BULLETPROOF ROW & COLUMN MASTER CSS
         ========================================================= */

      /* 1. NAVBAR - STRICT HORIZONTAL ROW IN ONE LINE */
      nav {
        position: sticky !important;
        top: 0 !important;
        left: 0 !important;
        right: 0 !important;
        width: 100% !important;
        background: rgba(255, 255, 255, 0.98) !important;
        backdrop-filter: blur(18px) !important;
        -webkit-backdrop-filter: blur(18px) !important;
        border-bottom: 1px solid rgba(226, 232, 240, 0.9) !important;
        z-index: 9999 !important;
        box-shadow: 0 4px 20px -5px rgba(15, 23, 42, 0.05) !important;
        padding: 0 !important;
      }

      .nav__inner {
        max-width: 1320px !important;
        margin: 0 auto !important;
        padding: 0.9rem 2rem !important;
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 2rem !important;
        width: 100% !important;
        box-sizing: border-box !important;
      }

      .nav__links {
        display: flex !important;
        flex-direction: row !important; /* STRICT HORIZONTAL ROW */
        align-items: center !important;
        justify-content: center !important;
        gap: 1.75rem !important;
        list-style: none !important;
        margin: 0 !important;
        padding: 0 !important;
        flex-wrap: nowrap !important;
        position: static !important;
        transform: none !important;
        background: transparent !important;
        box-shadow: none !important;
        width: auto !important;
        height: auto !important;
      }

      .nav-link-item {
        white-space: nowrap !important;
        font-size: 0.95rem !important;
        font-weight: 600 !important;
        color: #334155 !important;
        padding: 8px 16px !important;
        border-radius: 10px !important;
        transition: all 0.2s ease !important;
        text-decoration: none !important;
        display: inline-block !important;
      }

      .nav-link-item:hover, .nav-link-item.active {
        color: #4f46e5 !important;
        background: rgba(79, 70, 229, 0.08) !important;
      }

      .nav__actions-group {
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        gap: 14px !important;
        flex-shrink: 0 !important;
      }

      .nav__menu__btn {
        display: none !important;
      }

      @media (max-width: 868px) {
        .nav__menu__btn {
          display: block !important;
        }
        .nav__links {
          display: none !important;
        }
        .nav__links.open {
          display: flex !important;
          flex-direction: column !important;
          position: absolute !important;
          top: 100% !important;
          left: 0 !important;
          right: 0 !important;
          background: #ffffff !important;
          padding: 1.5rem !important;
          box-shadow: 0 10px 25px rgba(0,0,0,0.1) !important;
          gap: 1rem !important;
        }
      }

      /* 2. HOW IT WORK SECTION - 3-COLUMN ROW */
      .about__container {
        max-width: 1280px !important;
        margin: 0 auto !important;
        padding: 5rem 1.5rem !important;
        text-align: center !important;
      }

      .about__grid {
        display: grid !important;
        grid-template-columns: repeat(3, 1fr) !important; /* 3 CARDS IN A ROW */
        gap: 2.5rem !important;
        max-width: 1200px !important;
        margin: 3.5rem auto 0 auto !important;
        align-items: stretch !important;
      }

      .about__card {
        background: #ffffff !important;
        border: 1px solid #e2e8f0 !important;
        border-radius: 24px !important;
        padding: 3rem 2rem !important;
        text-align: center !important;
        box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.05) !important;
        transition: all 0.3s ease !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: center !important;
        justify-content: flex-start !important;
      }

      .about__card:hover {
        transform: translateY(-8px) !important;
        box-shadow: 0 20px 35px -5px rgba(79, 70, 229, 0.15) !important;
        border-color: rgba(79, 70, 229, 0.4) !important;
      }

      .about__card span {
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        width: 72px !important;
        height: 72px !important;
        border-radius: 20px !important;
        margin-bottom: 1.5rem !important;
      }

      .about__card h4 {
        font-size: 1.25rem !important;
        font-weight: 800 !important;
        color: #0f172a !important;
        margin-bottom: 0.85rem !important;
      }

      .about__card p {
        font-size: 0.95rem !important;
        line-height: 1.65 !important;
        color: #64748b !important;
        margin: 0 !important;
      }

      /* 3. DEALS / FLEET SECTION - 3-COLUMN ROW */
      .deals__container {
        max-width: 1280px !important;
        margin: 0 auto !important;
        padding: 5rem 1.5rem !important;
      }

      .deals__container .tab__content {
        display: none !important;
      }

      .deals__container .tab__content.active {
        display: grid !important;
        grid-template-columns: repeat(3, 1fr) !important; /* 3 CARS IN A ROW */
        gap: 2.25rem !important;
        align-items: stretch !important;
      }

      .deals__card {
        background: #ffffff !important;
        border: 1px solid #e2e8f0 !important;
        border-radius: 24px !important;
        padding: 1.5rem !important;
        box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.05) !important;
        transition: all 0.3s ease !important;
        display: flex !important;
        flex-direction: column !important;
        justify-content: space-between !important;
      }

      .deals__card:hover {
        transform: translateY(-6px) !important;
        box-shadow: 0 20px 40px -8px rgba(79, 70, 229, 0.16) !important;
        border-color: rgba(79, 70, 229, 0.35) !important;
      }

      .deals__card img {
        width: 100% !important;
        height: 200px !important;
        object-fit: cover !important;
        border-radius: 16px !important;
        margin-bottom: 1.25rem !important;
      }

      .deals__card h4 {
        font-size: 1.35rem !important;
        font-weight: 800 !important;
        color: #0f172a !important;
        margin-bottom: 1rem !important;
      }

      .deals__card__grid {
        display: grid !important;
        grid-template-columns: repeat(2, 1fr) !important;
        gap: 0.75rem !important;
        margin-bottom: 1.25rem !important;
      }

      .deals__card__grid div {
        display: flex !important;
        align-items: center !important;
        gap: 8px !important;
        font-size: 0.88rem !important;
        font-weight: 600 !important;
        color: #475569 !important;
        background: #f8fafc !important;
        padding: 8px 12px !important;
        border-radius: 10px !important;
        border: 1px solid #e2e8f0 !important;
      }

      .deals__card__footer {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        padding-top: 1rem !important;
        border-top: 1px solid #f1f5f9 !important;
      }

      .deals__card__footer h3 {
        font-size: 1.5rem !important;
        font-weight: 900 !important;
        color: #0f172a !important;
      }

      .deals__card__footer h3 span {
        font-size: 0.85rem !important;
        font-weight: 600 !important;
        color: #64748b !important;
      }

      .deals__card__footer a {
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        color: #ffffff !important;
        padding: 10px 20px !important;
        border-radius: 50px !important;
        font-weight: 700 !important;
        font-size: 0.9rem !important;
        text-decoration: none !important;
        display: inline-flex !important;
        align-items: center !important;
        gap: 6px !important;
        transition: all 0.25s ease !important;
        box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3) !important;
      }

      .deals__card__footer a:hover {
        transform: translateY(-2px) !important;
        box-shadow: 0 8px 18px rgba(79, 70, 229, 0.45) !important;
      }

      /* 4. SUBSCRIBE SECTION - BALANCED 2-COLUMN ROW */
      .subscribe__container {
        max-width: 1200px !important;
        margin: 5rem auto !important;
        padding: 3.5rem 3rem !important;
        background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%) !important;
        border-radius: 30px !important;
        display: grid !important;
        grid-template-columns: 1fr 1fr !important;
        align-items: center !important;
        gap: 3.5rem !important;
        box-shadow: 0 25px 50px -12px rgba(15, 23, 42, 0.25) !important;
      }

      .subscribe__image img {
        width: 100% !important;
        max-width: 480px !important;
        height: 280px !important;
        object-fit: cover !important;
        border-radius: 20px !important;
        box-shadow: 0 15px 30px rgba(0, 0, 0, 0.4) !important;
      }

      .subscribe__content .section__header {
        color: #ffffff !important;
        text-align: left !important;
        font-size: 2.2rem !important;
        font-weight: 800 !important;
        margin-bottom: 1rem !important;
      }

      .subscribe__content .section__description {
        color: #94a3b8 !important;
        text-align: left !important;
        font-size: 1rem !important;
        line-height: 1.65 !important;
        margin-bottom: 2rem !important;
      }

      .subscribe__content form {
        display: flex !important;
        align-items: center !important;
        background: rgba(255, 255, 255, 0.1) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        border-radius: 50px !important;
        padding: 6px 8px 6px 20px !important;
        max-width: 520px !important;
      }

      .subscribe__content form input {
        flex: 1 !important;
        background: transparent !important;
        border: none !important;
        outline: none !important;
        color: #ffffff !important;
        font-size: 0.95rem !important;
        padding: 10px 0 !important;
      }

      .subscribe__content form button {
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        color: #ffffff !important;
        padding: 12px 28px !important;
        border-radius: 50px !important;
        border: none !important;
        font-weight: 700 !important;
        font-size: 0.95rem !important;
        cursor: pointer !important;
        transition: all 0.25s ease !important;
      }

      /* RESPONSIVE BREAKPOINTS */
      @media (max-width: 1024px) {
        .about__grid {
          grid-template-columns: repeat(2, 1fr) !important;
        }
        .deals__container .tab__content.active {
          grid-template-columns: repeat(2, 1fr) !important;
        }
        .subscribe__container {
          grid-template-columns: 1fr !important;
          padding: 2.5rem 1.5rem !important;
        }
      }

      @media (max-width: 640px) {
        .about__grid {
          grid-template-columns: 1fr !important;
        }
        .deals__container .tab__content.active {
          grid-template-columns: 1fr !important;
        }
      }
  
    
      /* =========================================================
         NEW USER PROFILE PILL COLOR OVERHAUL (VIBRANT GRADIENT)
         ========================================================= */
      .btn-nav-auth,
      .profile-chip {
        display: inline-flex !important;
        align-items: center !important;
        gap: 10px !important;
        padding: 8px 20px !important;
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        border-radius: 50px !important;
        color: #ffffff !important;
        font-size: 0.92rem !important;
        font-weight: 700 !important;
        cursor: pointer !important;
        transition: all 0.25s ease !important;
        border: 1.5px solid rgba(255, 255, 255, 0.3) !important;
        box-shadow: 0 4px 15px rgba(79, 70, 229, 0.35) !important;
        white-space: nowrap !important;
      }

      .btn-nav-auth:hover,
      .profile-chip:hover {
        background: linear-gradient(135deg, #4338ca 0%, #6d28d9 100%) !important;
        transform: translateY(-2px) !important;
        box-shadow: 0 8px 22px rgba(79, 70, 229, 0.5) !important;
      }

      .profile-avatar {
        width: 28px !important;
        height: 28px !important;
        border-radius: 50% !important;
        background: rgba(255, 255, 255, 0.25) !important;
        color: #ffffff !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
      }

      .profile-avatar svg {
        stroke: #ffffff !important;
      }

      .profile-chip-name {
        color: #ffffff !important;
        font-weight: 700 !important;
        font-size: 0.92rem !important;
      }

      .profile-chevron {
        stroke: #ffffff !important;
        color: #ffffff !important;
        opacity: 0.9;
      }

      /* =========================================================
         AUTH WALL OVERLAY - "FIRST LOGIN THEN OPEN WEBSITE"
         ========================================================= */
      body.locked-screen {
        overflow: hidden !important;
        height: 100vh !important;
      }

      #auth-overlay {
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        background: radial-gradient(circle at center, rgba(15, 23, 42, 0.92) 0%, rgba(11, 17, 32, 0.98) 100%) !important;
        backdrop-filter: blur(25px) !important;
        -webkit-backdrop-filter: blur(25px) !important;
        z-index: 100000 !important;
        display: flex !important;
        justify-content: center !important;
        align-items: center !important;
        transition: opacity 0.5s ease, visibility 0.5s ease !important;
        padding: 1.5rem !important;
        box-sizing: border-box !important;
      }

      .auth-card-modern {
        background: #ffffff !important;
        padding: 2.75rem 2.25rem !important;
        border-radius: 28px !important;
        width: 100% !important;
        max-width: 460px !important;
        box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.1) !important;
        animation: authSlideUp 0.45s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
        box-sizing: border-box !important;
        text-align: center !important;
      }

      @keyframes authSlideUp {
        from { transform: translateY(40px) scale(0.96); opacity: 0; }
        to { transform: translateY(0) scale(1); opacity: 1; }
      }

      .auth-card-header h2 {
        font-size: 1.65rem !important;
        font-weight: 800 !important;
        color: #0f172a !important;
        margin-bottom: 0.5rem !important;
