      }
  
    
      /* =========================================================
         ULTRA GLOSSY & UNIFIED SHAPE MEASUREMENT MASTER STYLES
         ========================================================= */

      :root {
        --site-max-width: 1280px;
        --glass-bg: rgba(255, 255, 255, 0.88);
        --glass-border: 1px solid rgba(255, 255, 255, 0.9);
        --glass-shadow: 0 20px 40px -15px rgba(15, 23, 42, 0.07), inset 0 1px 1px rgba(255, 255, 255, 0.95);
        --glass-hover-shadow: 0 25px 50px -10px rgba(79, 70, 229, 0.2), inset 0 1px 1px rgba(255, 255, 255, 1);
      }

      /* Subtle Ambient Background Mesh */
      body {
        background-color: #f8fafc !important;
        background-image: 
          radial-gradient(at 0% 0%, rgba(99, 102, 241, 0.06) 0px, transparent 50%),
          radial-gradient(at 100% 0%, rgba(168, 85, 247, 0.05) 0px, transparent 50%),
          radial-gradient(at 50% 50%, rgba(236, 72, 153, 0.03) 0px, transparent 50%),
          radial-gradient(at 100% 100%, rgba(99, 102, 241, 0.05) 0px, transparent 50%) !important;
        background-attachment: fixed !important;
      }

      /* UNIFIED CONTAINER MEASUREMENT ACROSS ALL SECTIONS */
      .section__container,
      .nav__inner,
      .header__container,
      .about__container,
      .deals__container,
      .choose__container,
      .subscribe__container,
      .client__container,
      .footer__container,
      .footer__bar {
        max-width: var(--site-max-width) !important;
        margin-left: auto !important;
        margin-right: auto !important;
        padding-left: 2rem !important;
        padding-right: 2rem !important;
        box-sizing: border-box !important;
      }

      /* UNIFIED SECTION HEADERS */
      .section__header {
        font-size: 2.6rem !important;
        font-weight: 900 !important;
        color: #0f172a !important;
        letter-spacing: -0.03em !important;
        line-height: 1.15 !important;
        text-align: center !important;
        margin-bottom: 0.85rem !important;
      }

      .section__description {
        font-size: 1.05rem !important;
        line-height: 1.7 !important;
        color: #64748b !important;
        text-align: center !important;
        max-width: 640px !important;
        margin: 0 auto 3.5rem auto !important;
      }

      /* 1. GLOSSY NAVBAR */
      nav {
        position: sticky !important;
        top: 0 !important;
        left: 0 !important;
        right: 0 !important;
        width: 100% !important;
        background: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(24px) saturate(190%) !important;
        -webkit-backdrop-filter: blur(24px) saturate(190%) !important;
        border-bottom: 1px solid rgba(226, 232, 240, 0.8) !important;
        z-index: 9999 !important;
        box-shadow: 0 10px 30px -10px rgba(15, 23, 42, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;
      }

      .nav__inner {
        padding: 0.95rem 2rem !important;
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 2rem !important;
      }

      .nav-link-item {
        white-space: nowrap !important;
        font-size: 0.95rem !important;
        font-weight: 600 !important;
        color: #334155 !important;
        padding: 8px 18px !important;
        border-radius: 50px !important;
        transition: all 0.25s ease !important;
        text-decoration: none !important;
        border: 1px solid transparent !important;
      }

      .nav-link-item:hover, .nav-link-item.active {
        color: #4f46e5 !important;
        background: rgba(79, 70, 229, 0.08) !important;
        border-color: rgba(79, 70, 229, 0.2) !important;
        box-shadow: 0 2px 8px rgba(79, 70, 229, 0.06), inset 0 1px 0 rgba(255, 255, 255, 0.8) !important;
      }

      /* 2. GLOSSY HERO CAR DISPLAY */
      .header__container {
        padding-top: 4rem !important;
        padding-bottom: 7rem !important;
        display: grid !important;
        grid-template-columns: 1.05fr 0.95fr !important;
        align-items: center !important;
        gap: 3.5rem !important;
      }

      .hero-bg-card {
        position: absolute;
        top: 15px;
        right: 0;
        bottom: 15px;
        left: 20px;
        background: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(240, 243, 255, 0.65) 100%) !important;
        backdrop-filter: blur(20px) !important;
        border-radius: 36px !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        box-shadow: 0 30px 60px -15px rgba(79, 70, 229, 0.16), inset 0 2px 4px rgba(255, 255, 255, 1) !important;
        z-index: 0;
      }

      .hero-floating-card {
        background: rgba(255, 255, 255, 0.92) !important;
        backdrop-filter: blur(20px) !important;
        -webkit-backdrop-filter: blur(20px) !important;
        padding: 12px 20px !important;
        border-radius: 20px !important;
        box-shadow: 0 16px 36px -8px rgba(15, 23, 42, 0.12), inset 0 1px 1px rgba(255, 255, 255, 1) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
      }

      /* 3. GLOSSY FLOATING SEARCH FORM */
      .header__form {
        max-width: var(--site-max-width) !important;
        margin: -4rem auto 4.5rem auto !important;
        position: relative !important;
        z-index: 10 !important;
        padding: 0 2rem !important;
        box-sizing: border-box !important;
      }

      .header__form form {
        background: rgba(255, 255, 255, 0.92) !important;
        backdrop-filter: blur(28px) saturate(190%) !important;
        -webkit-backdrop-filter: blur(28px) saturate(190%) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        box-shadow: 0 30px 70px -15px rgba(15, 23, 42, 0.14), inset 0 1px 0 rgba(255, 255, 255, 1) !important;
        border-radius: 30px !important;
        padding: 2rem 2.5rem !important;
        display: grid !important;
        grid-template-columns: 1.3fr 1fr 1fr auto !important;
        align-items: flex-end !important;
        gap: 1.5rem !important;
      }

      .header__form input {
        background: rgba(248, 250, 252, 0.9) !important;
        border: 1.5px solid rgba(226, 232, 240, 0.9) !important;
        border-radius: 16px !important;
        padding: 14px 18px !important;
        transition: all 0.25s ease !important;
      }

      .header__form input:focus {
        border-color: #4f46e5 !important;
        background: #ffffff !important;
        box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12), inset 0 1px 2px rgba(0, 0, 0, 0.02) !important;
      }

      .btn-search-primary {
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        box-shadow: 0 12px 28px -5px rgba(79, 70, 229, 0.55), inset 0 1px 1px rgba(255, 255, 255, 0.4) !important;
        border: 1px solid rgba(255, 255, 255, 0.25) !important;
        border-radius: 16px !important;
        height: 52px !important;
        padding: 0 32px !important;
      }

      /* 4. GLOSSY HOW IT WORKS SECTION */
      .about__container {
        padding-block: 5.5rem !important;
      }

      .about__grid {
        display: grid !important;
        grid-template-columns: repeat(3, 1fr) !important;
        gap: 2.5rem !important;
        align-items: stretch !important;
      }

      .about__card {
        background: rgba(255, 255, 255, 0.88) !important;
        backdrop-filter: blur(18px) !important;
        -webkit-backdrop-filter: blur(18px) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        border-radius: 28px !important;
        padding: 3rem 2.25rem !important;
        text-align: center !important;
        box-shadow: var(--glass-shadow) !important;
        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
      }

      .about__card:hover {
        transform: translateY(-8px) scale(1.02) !important;
        box-shadow: var(--glass-hover-shadow) !important;
        border-color: rgba(79, 70, 229, 0.4) !important;
      }

      .about__card span {
        width: 76px !important;
        height: 76px !important;
        border-radius: 22px !important;
        margin-bottom: 1.75rem !important;
        box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05), inset 0 1px 1px rgba(255, 255, 255, 0.8) !important;
      }

      /* 5. GLOSSY FLEET TABS & CARDS */
      .deals__container {
        padding-block: 5.5rem !important;
      }

      .deals__tabs {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        gap: 8px !important;
        background: rgba(255, 255, 255, 0.75) !important;
        backdrop-filter: blur(18px) !important;
        padding: 6px !important;
        border-radius: 50px !important;
        border: 1px solid rgba(226, 232, 240, 0.8) !important;
        max-width: fit-content !important;
        margin: 0 auto 3.5rem auto !important;
        box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.04), inset 0 1px 1px rgba(255, 255, 255, 0.9) !important;
      }

      .deals__tabs .btn {
        padding: 10px 26px !important;
        border-radius: 50px !important;
        font-weight: 700 !important;
        font-size: 0.95rem !important;
        color: #475569 !important;
        background: transparent !important;
        border: none !important;
        cursor: pointer !important;
        transition: all 0.25s ease !important;
      }

      .deals__tabs .btn.active {
        background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%) !important;
        color: #ffffff !important;
        box-shadow: 0 8px 18px rgba(79, 70, 229, 0.4), inset 0 1px 1px rgba(255, 255, 255, 0.4) !important;
      }

      .deals__container .tab__content.active {
        display: grid !important;
        grid-template-columns: repeat(3, 1fr) !important;
        gap: 2.5rem !important;
        align-items: stretch !important;
      }

      .deals__card {
        background: rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: blur(20px) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        border-radius: 28px !important;
        padding: 1.65rem !important;
        box-shadow: var(--glass-shadow) !important;
        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
        display: flex !important;
        flex-direction: column !important;
        justify-content: space-between !important;
        height: 100% !important;
      }

      .deals__card:hover {
        transform: translateY(-8px) scale(1.01) !important;
        box-shadow: var(--glass-hover-shadow) !important;
        border-color: rgba(99, 102, 241, 0.45) !important;
      }

      .deals__card img {
        width: 100% !important;
        height: 210px !important;
        object-fit: cover !important;
        border-radius: 20px !important;
        margin-bottom: 1.25rem !important;
        box-shadow: 0 8px 20px rgba(0, 0, 0, 0.06) !important;
      }

      /* 6. GLOSSY WHY CHOOSE US SECTION */
      .choose__container {
        padding-block: 5.5rem !important;
        display: grid !important;
        grid-template-columns: 1fr 1.15fr !important;
        align-items: center !important;
        gap: 4rem !important;
      }

      .choose__image img {
        width: 100% !important;
        height: 480px !important;
        object-fit: cover !important;
        border-radius: 32px !important;
        box-shadow: 0 30px 60px -15px rgba(15, 23, 42, 0.25), inset 0 2px 4px rgba(255, 255, 255, 0.8) !important;
      }

      .choose__card {
        background: rgba(255, 255, 255, 0.88) !important;
        backdrop-filter: blur(16px) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        border-radius: 20px !important;
        padding: 1.35rem !important;
        box-shadow: var(--glass-shadow) !important;
        transition: all 0.25s ease !important;
      }

      .choose__card:hover {
        transform: translateY(-4px) !important;
        box-shadow: var(--glass-hover-shadow) !important;
        border-color: rgba(79, 70, 229, 0.35) !important;
      }

      .choose__card span {
        width: 46px !important;
        height: 46px !important;
        border-radius: 14px !important;
        background: linear-gradient(135deg, rgba(79, 70, 229, 0.12) 0%, rgba(124, 58, 237, 0.15) 100%) !important;
        box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.8) !important;
      }

      /* 7. GLOSSY DARK SUBSCRIBE BANNER */
      .subscribe__container {
        margin: 5.5rem auto !important;
        padding: 4rem 3.5rem !important;
        background: 
          radial-gradient(circle at 80% 20%, rgba(99, 102, 241, 0.3) 0%, transparent 60%),
          radial-gradient(circle at 20% 80%, rgba(236, 72, 153, 0.15) 0%, transparent 60%),
          linear-gradient(135deg, #0b1120 0%, #1e1b4b 100%) !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;
        border-radius: 36px !important;
        box-shadow: 0 35px 70px -15px rgba(11, 17, 32, 0.45), inset 0 1px 1px rgba(255, 255, 255, 0.2) !important;
      }

      .subscribe__image img {
        border-radius: 24px !important;
        box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5) !important;
      }

      /* 8. GLOSSY REVIEWS / TESTIMONIALS CARDS */
      .client__container {
        padding-block: 5.5rem !important;
      }

      .client__card {
        background: rgba(255, 255, 255, 0.9) !important;
        backdrop-filter: blur(20px) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        border-radius: 28px !important;
        padding: 2.25rem !important;
        box-shadow: var(--glass-shadow) !important;
        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
      }

      .client__card:hover {
        transform: translateY(-8px) !important;
        box-shadow: var(--glass-hover-shadow) !important;
        border-color: rgba(79, 70, 229, 0.35) !important;
      }

      /* 9. GLOSSY FOOTER */
      .footer {
        background: linear-gradient(180deg, #0f172a 0%, #080d1a 100%) !important;
        border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
        box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.1) !important;
      }

      .footer__container {
        padding-top: 5.5rem !important;
        padding-bottom: 4rem !important;
      }
  
    
      /* =========================================================
         SCENARIO 1 & 2: WHY CHOOSE US & SUBSCRIBE - BIG CAR & GLOSS
         ========================================================= */

      /* WHY CHOOSE US */
      .choose__container {
        display: grid !important;
        grid-template-columns: 1fr 1.15fr !important;
        align-items: center !important;
        gap: 4.5rem !important;
        padding-block: 6rem !important;
      }

      .choose__image-col {
        position: relative;
        width: 100%;
      }

      .choose__stage {
        position: relative;
        width: 100%;
        min-height: 480px;
        display: flex;
        align-items: center;
        justify-content: center;
      }

      .choose-bg-card {
        position: absolute;
        top: 15px;
        right: 0;
        bottom: 15px;
        left: 20px;
        background: linear-gradient(135deg, rgba(255, 255, 255, 0.85) 0%, rgba(240, 243, 255, 0.7) 100%) !important;
        backdrop-filter: blur(20px) !important;
        border-radius: 36px !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        box-shadow: 0 30px 60px -15px rgba(79, 70, 229, 0.16), inset 0 2px 4px rgba(255, 255, 255, 1) !important;
        z-index: 0;
      }

      .choose-bg-glow {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 400px;
        height: 400px;
        background: radial-gradient(circle, rgba(99, 102, 241, 0.22) 0%, rgba(147, 51, 234, 0.08) 50%, transparent 70%);
        filter: blur(40px);
        pointer-events: none;
        z-index: 0;
      }

      /* BIG CAR DISPLAY IN WHY CHOOSE US */
      .choose-main-car {
        position: relative !important;
        z-index: 2 !important;
        width: 135% !important;
        max-width: 720px !important;
        height: auto !important;
        object-fit: contain !important;
        transform: scale(1.22) translateX(3%) !important;
        filter: drop-shadow(0 25px 35px rgba(15, 23, 42, 0.3)) !important;
        transition: transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
      }

      .choose__stage:hover .choose-main-car {
        transform: scale(1.28) translateY(-6px) translateX(3%) !important;
        filter: drop-shadow(0 35px 45px rgba(15, 23, 42, 0.4)) !important;
      }

      .choose-car-ground-shadow {
        position: absolute;
        bottom: 22px;
        left: 50%;
        transform: translateX(-47%);
        width: 88%;
        max-width: 600px;
        height: 30px;
        background: radial-gradient(ellipse at center, rgba(15, 23, 42, 0.45) 0%, rgba(15, 23, 42, 0.12) 50%, transparent 75%);
        border-radius: 50%;
        filter: blur(7px);
        z-index: 1;
      }

      .choose-floating-badge {
        position: absolute !important;
        z-index: 3 !important;
        background: rgba(255, 255, 255, 0.94) !important;
        backdrop-filter: blur(18px) !important;
        padding: 10px 18px !important;
        border-radius: 18px !important;
        display: flex !important;
        align-items: center !important;
        gap: 12px !important;
        box-shadow: 0 16px 32px -8px rgba(15, 23, 42, 0.12), inset 0 1px 1px rgba(255, 255, 255, 1) !important;
        border: 1px solid rgba(255, 255, 255, 0.95) !important;
        animation: floatSlow 4.5s ease-in-out infinite alternate !important;
      }

      .choose-badge-top {
        top: 25px !important;
        right: -10px !important;
      }

      .choose-badge-bottom {
        bottom: 25px !important;
        left: 0px !important;
        animation-delay: -2.25s !important;
      }

      .choose-badge-icon {
        width: 38px;
        height: 38px;
        border-radius: 12px;
        background: rgba(79, 70, 229, 0.1);
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
      }

      .choose-badge-icon.gold {
        background: rgba(245, 158, 11, 0.12);
      }

      /* 2x3 BALANCED GRID */
      .choose__grid {
        display: grid !important;
