      }
      .res-input-group {
        width: 100% !important;
        box-sizing: border-box !important;
        min-width: 0 !important;
      }
      .res-input-group input {
        width: 100% !important;
        min-width: 0 !important;
        box-sizing: border-box !important;
      }
      .res-dates-row {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
        gap: 10px !important;
        width: 100% !important;
        box-sizing: border-box !important;
      }
      .res-dates-row .res-input-group {
        min-width: 0 !important;
      }
      .res-dates-row .res-input-group input {
        width: 100% !important;
        min-width: 0 !important;
      }
      .res-options-grid {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
        gap: 10px !important;
        width: 100% !important;
        box-sizing: border-box !important;
      }
      .res-option-card {
        min-width: 0 !important;
        box-sizing: border-box !important;
      }
      .opt-content {
        min-width: 0 !important;
        overflow: hidden !important;
      }
      .res-promo-box {
        width: 100% !important;
        box-sizing: border-box !important;
        min-width: 0 !important;
      }
      .promo-input-row {
        display: flex !important;
        gap: 8px !important;
        width: 100% !important;
        box-sizing: border-box !important;
      }
      .promo-input-row input {
        flex: 1 1 auto !important;
        min-width: 0 !important;
        width: auto !important;
        box-sizing: border-box !important;
      }
      .promo-input-row button {
        flex: 0 0 auto !important;
        white-space: nowrap !important;
        padding: 9px 18px !important;
      }
      .res-invoice-card {
        width: 100% !important;
        box-sizing: border-box !important;
        min-width: 0 !important;
        padding: 1.15rem 1.25rem !important;
      }
      .invoice-row {
        gap: 8px !important;
        width: 100% !important;
        box-sizing: border-box !important;
      }
      .invoice-row span {
        min-width: 0 !important;
