              <option value="Hazrat Shahjalal Int'l Airport (DAC), Dhaka">
              <option value="Gulshan-2 Diplomatic Zone, Dhaka">
              <option value="Banani Commercial Area, Dhaka">
              <option value="Dhanmondi Lake & Satmasjid Rd, Dhaka">
              <option value="Uttara Sector 3 / Sector 7, Dhaka">
              <option value="Agrabad Commercial Area, Chittagong">
              <option value="Kolatoli Beach Road, Cox's Bazar">
              <option value="Zindabazar City Center, Sylhet">
              <option value="Bashundhara R/A Gate, Dhaka">
              <option value="Mirpur DOHS, Dhaka">
            </datalist>
          </div>
        </div>
        <div class="input__group">
