    <script src="https://unpkg.com/scrollreveal"></script>
    <script src="https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js"></script>
    
    <script>
      const authOverlay = document.getElementById('auth-overlay');
      const tabLogin = document.getElementById('tab-login');
      const tabRegister = document.getElementById('tab-register');
      const nameGroup = document.getElementById('name-group');
      const passwordGroup = document.getElementById('password-group');
      const authName = document.getElementById('auth-name');
      const authPassword = document.getElementById('auth-password');
      const authBtn = document.getElementById('auth-btn');
      const authTitle = document.getElementById('auth-title');
      const authSubtitle = document.getElementById('auth-subtitle');
      const authForm = document.getElementById('auth-form');
      const authSuccess = document.getElementById('auth-success');
      const authSuccessMsg = document.getElementById('auth-success-msg');
      const quickDemoLoginBtn = document.getElementById('quick-demo-login-btn');
      let isLogin = true;

      tabLogin.addEventListener('click', () => {
        isLogin = true;
        tabLogin.classList.add('active');
        tabRegister.classList.remove('active');
        nameGroup.style.display = 'none';
        if (authName) authName.required = false;
        authBtn.innerHTML = '<span>Sign In & Open Website</span> <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg>';
        authTitle.innerText = 'Welcome Back';
        if (authSubtitle) authSubtitle.innerText = 'Please enter your credentials to open the platform.';
      });

      tabRegister.addEventListener('click', () => {
        isLogin = false;
        tabRegister.classList.add('active');
        tabLogin.classList.remove('active');
        nameGroup.style.display = 'block';
        if (authName) authName.required = true;
        authBtn.innerHTML = '<span>Create Account & Open Website</span> <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg>';
        authTitle.innerText = 'Create an Account';
        if (authSubtitle) authSubtitle.innerText = 'Register now to unlock verified rentals across Bangladesh.';
      });

      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';
      let currentUser = null;

      // FIRST IN LOGIN / SIGN IN THEN OPEN WEBSITE:
      // Require active session authentication. If not yet logged in during this active session, KEEP SCREEN LOCKED!
      const sessionAuth = sessionStorage.getItem("car_rental_authenticated");
      try {
        const saved = localStorage.getItem("car_rental_current_user");
        if (saved && sessionAuth === "true") {
          currentUser = JSON.parse(saved);
        }
      } catch (e) {}

      function unlockWebsite(user) {
        currentUser = user;
        sessionStorage.setItem("car_rental_authenticated", "true");
        localStorage.setItem("car_rental_current_user", JSON.stringify(user));

        authForm.style.display = "none";
        document.querySelector('.auth-tabs').style.display = "none";
        document.querySelector('.auth-card-header').style.display = "none";
        authSuccess.style.display = "block";
        authSuccessMsg.innerText = isLogin ? "Welcome back, " + (user.name || "Customer") + "!" : "Registration Successful!";

        setTimeout(() => {
          authOverlay.style.opacity = '0';
          authOverlay.style.visibility = 'hidden';
          authOverlay.style.pointerEvents = 'none';
          document.body.classList.remove('locked-screen');
          renderUserProfile(user.name || user.email.split('@')[0] || 'User', user.email, user.phone);
          initScrollReveal();
          showToast("Welcome to CarRental BD! Enjoy your ride.", "success");
        }, 900);
