      // Check if already authenticated this session
      if (currentUser && sessionAuth === "true") {
        authOverlay.style.opacity = '0';
        authOverlay.style.visibility = 'hidden';
        authOverlay.style.pointerEvents = 'none';
        document.body.classList.remove('locked-screen');
        renderUserProfile(currentUser.name || 'asifhasanarpon21', currentUser.email, currentUser.phone);
        setTimeout(() => initScrollReveal(), 100);
      } else {
        // LOCK SCREEN AND DEMAND LOGIN FIRST
        document.body.classList.add('locked-screen');
        authOverlay.style.opacity = '1';
        authOverlay.style.visibility = 'visible';
        authOverlay.style.pointerEvents = 'auto';
      }

      // 1-Click Instant Login handler
      if (quickDemoLoginBtn) {
        quickDemoLoginBtn.addEventListener('click', (e) => {
          e.preventDefault();
          const demoUser = {
            name: "Asif Hasan",
            email: "asifhasanarpon21@gmail.com",
            phone: "+880 1618-956088"
          };
          unlockWebsite(demoUser);
        });
      }

      authForm.addEventListener('submit', async (e) => {
        e.preventDefault();

        const email = document.getElementById('auth-email').value.trim();
        const phone = document.getElementById('auth-phone').value.trim();
        const password = authPassword.value;
        let fullName = isLogin ? (email.split('@')[0] || "User") : (authName ? authName.value.trim() : "User");

        const endpoint = isLogin ? '/login' : '/register';
        let authedUser = { name: fullName, email, phone };

        try {
          const res = await fetch(endpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Accept': 'application/json',
              'X-CSRF-TOKEN': csrfToken
            },
            body: JSON.stringify({ name: fullName, email, phone, password })
          });
          const data = await res.json();
          if (!res.ok) {
            const firstErr = data.errors ? Object.values(data.errors)[0][0] : (data.message || 'Authentication failed.');
            showToast(firstErr, 'error');
            return;
          }
          if (data.user) {
            authedUser = data.user;
          }
        } catch (err) {
          // Fallback if local server offline
        }

        unlockWebsite(authedUser);
      });

      window.addEventListener("click", () => {
