      const rentBtns = document.querySelectorAll(".deals__card__footer a");
      rentBtns.forEach(btn => {
        btn.addEventListener("click", async (e) => {
          e.preventDefault();
          
          // Check if Search Form inputs are filled
          const locationVal = document.getElementById("location").value.trim();
          const startVal = document.getElementById("start").value.trim();
          const stopVal = document.getElementById("stop").value.trim();

          if (!locationVal || !startVal || !stopVal) {
             showToast("Please complete the pick-up and return details before renting a car.", "error");
             document.getElementById("search-form").scrollIntoView({ behavior: "smooth", block: "center" });
             return;
          }

          if (new Date(stopVal) < new Date(startVal)) {
             showToast("Return date & time must be after the pick-up date & time.", "error");
             document.getElementById("search-form").scrollIntoView({ behavior: "smooth", block: "center" });
             return;
          }

          const card = e.target.closest('.deals__card');
          const carName = card.querySelector('h4').innerText;

          const userEmail = (currentUser && currentUser.email) || document.getElementById('auth-email').value || "Not provided";
          const userPhone = (currentUser && currentUser.phone) || document.getElementById('auth-phone').value || "Not provided";

          try {
            const res = await fetch('/bookings', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-CSRF-TOKEN': csrfToken
              },
              body: JSON.stringify({
                car_name: carName,
                pickup_location: locationVal,
                start_time: startVal,
                return_time: stopVal,
                email: userEmail !== "Not provided" ? userEmail : null,
                phone: userPhone !== "Not provided" ? userPhone : null
              })
            });
            if (!res.ok) {
              const errData = await res.json();
              const msg = errData.errors ? Object.values(errData.errors)[0][0] : (errData.message || 'Booking failed.');
              showToast(msg, "error");
              return;
            }
          } catch (err) {
            // Fallback for offline preview
          }

          const newBooking = {
            id: Date.now(),
            car_name: carName,
            pickup_location: locationVal,
            start_time: startVal,
            return_time: stopVal,
            email: userEmail,
            phone: userPhone,
            driver_phone: '+880 1712-345678',
            status: 'confirmed',
            created_at: new Date().toISOString()
          };
          userBookings.unshift(newBooking);
          try {
            localStorage.setItem("car_rental_bookings", JSON.stringify(userBookings));
          } catch(e){}
          updateDashboardUI();

          showToast(`Booking saved for ${carName}!`, "success");
          showSuccessModal(carName, userEmail, userPhone, locationVal);
        });
      });

      // Dashboard Controller
      let userBookings = [];
      const dashModal = document.getElementById("dashboard-modal");
      const closeDashBtn = document.getElementById("close-dashboard-btn");
      const navDashLink = document.getElementById("nav-dashboard-link");
      const heroDashBtn = document.getElementById("hero-dashboard-btn");

      async function loadDashboardData() {
        try {
          const res = await fetch("/bookings");
          if (res.ok) {
            const data = await res.json();
            if (data.bookings && data.bookings.length > 0) {
              userBookings = data.bookings;
            }
          }
        } catch (e) {
          // Fallback to localStorage
        }
        try {
          const local = localStorage.getItem("car_rental_bookings");
          if (local && (!userBookings || userBookings.length === 0)) {
            userBookings = JSON.parse(local);
          }
        } catch (err) {}

        // If still empty, add default sample demo booking for rich preview
        if (userBookings.length === 0) {
          userBookings = [
            {
              id: 101,
              car_name: "Toyota Fortuner",
              pickup_location: "Dhaka, Gulshan-2",
              start_time: new Date().toISOString(),
              return_time: new Date(Date.now() + 86400000 * 2).toISOString(),
              driver_phone: "+880 1712-345678",
              status: "confirmed"
            }
          ];
        }

        updateDashboardUI();
      }

      function updateDashboardUI() {
        if (currentUser) {
          const nameEl = document.getElementById("dash-user-name");
          const emailEl = document.getElementById("dash-user-email");
          if (nameEl) nameEl.innerText = (currentUser.name || "Customer") + "'s Dashboard";
          if (emailEl) emailEl.innerText = currentUser.email || "asifhasanarpon21@gmail.com";
        }

        const total = userBookings.length;
        const active = userBookings.filter(b => b.status === "confirmed" || b.status === "active").length;
        const totalSpent = total * 175;
        const rewards = total * 150 + 200;

        const totalEl = document.getElementById("stat-total-bookings");
        const activeEl = document.getElementById("stat-active-rentals");
        const spentEl = document.getElementById("stat-total-spent");
        const rewardsEl = document.getElementById("stat-rewards");
        const countEl = document.getElementById("dash-booking-count");

        if (totalEl) totalEl.innerText = total;
        if (activeEl) activeEl.innerText = active;
        if (spentEl) spentEl.innerText = `$${totalSpent}`;
        if (rewardsEl) rewardsEl.innerText = `${rewards} Pts`;
        if (countEl) countEl.innerText = total;

        const navBadges = document.querySelectorAll(".nav-dash-badge");
        navBadges.forEach(b => b.innerText = total);

        renderBookingsList();
        renderActiveTrip();
      }

      
      // Enhanced Dashboard Booking Renderer with Cancel & Voucher Buttons
      function renderBookingsList() {
        const list = document.getElementById("bookings-list-container");
        if (!list) return;

        if (!userBookings || userBookings.length === 0) {
          list.innerHTML = `
            <div class="empty-state">
              <i class="ri-car-line empty-icon"></i>
              <p>No active or past bookings yet.</p>
              <button class="btn btn-hero-primary" onclick="closeDashboard(); document.getElementById('deals').scrollIntoView({behavior: 'smooth'})" style="margin-top: 10px;">Browse Vehicles</button>
            </div>
          `;
          return;
        }

        list.innerHTML = userBookings.map((b, idx) => {
          const isCancelled = (b.status === "cancelled");
          const refCode = b.ref_code || ("CR-2026-" + (90000 + (b.id % 9000)));
          const carImg = getCarImage(b.car_name);
          return `
            <div class="booking-item ${isCancelled ? 'cancelled-item' : ''}" style="display: flex; align-items: center; justify-content: space-between; padding: 14px 18px; border: 1.5px solid ${isCancelled ? '#fee2e2' : '#e2e8f0'}; border-radius: 16px; margin-bottom: 12px; background: ${isCancelled ? '#fff5f5' : '#ffffff'}; transition: all 0.2s;">
              <div style="display: flex; align-items: center; gap: 16px;">
                <img src="${carImg}" alt="${b.car_name}" style="width: 75px; height: 48px; object-fit: contain;" />
                <div>
                  <div style="display: flex; align-items: center; gap: 8px;">
                    <h4 style="margin: 0; font-size: 1rem; color: var(--text-dark);">${b.car_name}</h4>
                    <span class="${isCancelled ? 'badge-status-cancelled' : 'badge-status-confirmed'}">
                      <i class="${isCancelled ? 'ri-close-circle-fill' : 'ri-checkbox-circle-fill'}"></i>
                      ${isCancelled ? 'Cancelled' : 'Confirmed'}
                    </span>
                  </div>
                  <div style="font-size: 0.78rem; color: #64748b; margin-top: 3px; display: flex; gap: 12px; flex-wrap: wrap;">
                    <span><i class="ri-barcode-line"></i> ${refCode}</span>
                    <span><i class="ri-map-pin-line"></i> ${b.pickup_location || 'Dhaka'}</span>
                    <span><i class="ri-time-line"></i> ${formatDateTime(b.start_time)}</span>
                  </div>
                </div>
              </div>
              <div style="display: flex; align-items: center; gap: 8px;">
                <button type="button" class="btn-dash-action-view" onclick="viewVoucherForBooking('${b.id}')"><i class="ri-file-text-line"></i> Receipt</button>
                ${!isCancelled ? `
                  <button type="button" class="btn-dash-action-cancel" onclick="triggerCancelBooking('${b.id}')"><i class="ri-close-circle-line"></i> Cancel</button>
                ` : `
                  <button type="button" class="btn-dash-action-view" style="color: #10b981; border-color: #a7f3d0;" onclick="openReservationModal('${b.car_name}')"><i class="ri-refresh-line"></i> Re-Book</button>
                `}
              </div>
            </div>
          `;
        }).join("");
      }

      function renderActiveTrip() {
        const container = document.getElementById("active-trip-container");
        if (!container) return;

        // Find first confirmed booking
        const active = userBookings.find(b => b.status === "confirmed");
        if (!active) {
          container.innerHTML = `
            <div class="empty-state">
              <i class="ri-navigation-line empty-icon"></i>
              <p>No active rental at the moment.</p>
              <button class="btn btn-hero-primary" onclick="closeDashboard(); document.getElementById('deals').scrollIntoView({behavior: 'smooth'})" style="margin-top: 10px;">Reserve a Car Now</button>
            </div>
          `;
          return;
        }

        const carImg = getCarImage(active.car_name);
        const refCode = active.ref_code || ("CR-2026-" + (90000 + (active.id % 9000)));
        container.innerHTML = `
          <div style="background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 20px; padding: 1.5rem; box-shadow: 0 4px 15px rgba(0,0,0,0.04);">
            <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 1rem;">
              <div>
                <span class="badge-status-confirmed"><i class="ri-flashlight-line"></i> Guaranteed & Ready</span>
                <h3 style="margin: 6px 0 2px; font-size: 1.4rem; color: var(--text-dark);">${active.car_name}</h3>
                <small style="color: #64748b;"><i class="ri-barcode-line"></i> Ref: ${refCode}</small>
              </div>
              <img src="${carImg}" alt="${active.car_name}" style="width: 120px; height: 70px; object-fit: contain;" />
            </div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; background: #f8fafc; padding: 12px; border-radius: 12px; margin-bottom: 1.25rem;">
              <div>
                <small style="color: #64748b; display: block;"><i class="ri-map-pin-line"></i> Pick-up Point</small>
                <strong style="font-size: 0.85rem; color: var(--text-dark);">${active.pickup_location || 'Hazrat Shahjalal Int\'l Airport'}</strong>
              </div>
              <div>
                <small style="color: #64748b; display: block;"><i class="ri-time-line"></i> Schedule</small>
                <strong style="font-size: 0.85rem; color: var(--text-dark);">${formatDateTime(active.start_time)}</strong>
              </div>
            </div>
            <div style="display: flex; gap: 10px;">
              <button type="button" class="btn-dash-action-view" style="flex: 1; justify-content: center; padding: 10px;" onclick="viewVoucherForBooking('${active.id}')"><i class="ri-printer-line"></i> Print Booking Voucher</button>
              <button type="button" class="btn-dash-action-cancel" style="flex: 1; justify-content: center; padding: 10px;" onclick="triggerCancelBooking('${active.id}')"><i class="ri-close-circle-line"></i> Cancel Rental</button>
            </div>
          </div>
        `;
      }

      function getCarImage(carName) {
        const name = (carName || '').toLowerCase();
        if (name.includes('corolla')) return 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Toyota_Corolla.jpg';
        if (name.includes('innova')) return 'https://upload.wikimedia.org/wikipedia/commons/c/ca/Toyota_Innova_2.8_V_2021_%281%29.jpg';
        if (name.includes('fortuner')) return 'https://upload.wikimedia.org/wikipedia/commons/5/54/Toyota_Fortuner_White.jpg';
        if (name.includes('camry')) return 'https://upload.wikimedia.org/wikipedia/commons/6/6f/2018_GAC-Toyota_Camry_%28front%29.jpg';
        if (name.includes('noah')) return 'https://upload.wikimedia.org/wikipedia/commons/3/34/2022_Toyota_Noah_Hybrid_S-Z.jpg';
        if (name.includes('rav4')) return 'https://upload.wikimedia.org/wikipedia/commons/6/62/Toyota_RAV4_XLE_%28facelift%29_%28front%29.jpg';
        if (name.includes('tesla')) return 'https://upload.wikimedia.org/wikipedia/commons/3/3f/Tesla_Model_Y.jpg';
        if (name.includes('amaze')) return 'https://upload.wikimedia.org/wikipedia/commons/2/25/Honda_Amaze_front.jpg';
        return 'https://upload.wikimedia.org/wikipedia/commons/a/a5/Toyota_Corolla.jpg';
      }

      function formatDateTime(dtStr) {
        if (!dtStr) return 'Flexible';
        try {
          const d = new Date(dtStr);
          return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
        } catch (e) {
          return dtStr;
        }
      }

      function openDashboard(tabName = 'bookings') {
        if (dashModal) dashModal.classList.add("open");
        document.body.style.overflow = "hidden";
        if (tabName) switchDashboardTab(tabName);
        loadDashboardData();
      }

      function closeDashboard() {
        if (dashModal) dashModal.classList.remove("open");
        document.body.style.overflow = "";
      }

      function switchDashboardTab(tabName) {
        document.querySelectorAll(".dash-tab").forEach(t => {
          t.classList.toggle("active", t.dataset.tab === tabName);
        });
        document.querySelectorAll(".dash-tab-content").forEach(c => {
          c.classList.toggle("active", c.id === `dash-tab-${tabName}`);
        });
      }

      function cancelBooking(id) {
        if (confirm("Are you sure you want to cancel this car rental reservation?")) {
          userBookings = userBookings.filter((b, idx) => (b.id !== id && idx !== id));
          try {
            localStorage.setItem("car_rental_bookings", JSON.stringify(userBookings));
          } catch(e){}
          updateDashboardUI();
          showToast("Booking cancelled successfully.", "success");
        }
      }

      function printBookingReceipt(car, loc, start, end) {
        const w = window.open('', '_blank');
        w.document.write(`
          <!DOCTYPE html>
          <html>
            <head><title>Car Rental Receipt - ${car}</title></head>
            <body style="font-family: sans-serif; padding: 40px; color: #1e293b; max-width: 600px; margin: auto;">
              <h2 style="color: #4f46e5;">CarRental Bangladesh</h2>
              <hr style="border: 0; border-top: 2px solid #e2e8f0; margin: 20px 0;" />
              <h3>Official Booking Slip</h3>
              <p><strong>Vehicle:</strong> ${car}</p>
              <p><strong>Pickup Location:</strong> ${loc}</p>
              <p><strong>Start Time:</strong> ${formatDateTime(start)}</p>
              <p><strong>Return Time:</strong> ${formatDateTime(end)}</p>
              <p><strong>Status:</strong> Confirmed & Verified</p>
              <p><strong>Driver Hotline:</strong> +880 1712-345678</p>
              <hr style="border: 0; border-top: 1px dashed #cbd5e1; margin: 20px 0;" />
              <p style="font-size: 12px; color: #64748b;">Thank you for choosing CarRental BD! Have a safe and comfortable trip.</p>
            </body>
          </html>
        `);
        w.print();
      }

