      let activeCategoryFilter = "all";
      let activeBrandFilter = "All";
      let activeSearchQuery = "";
      let activeSortOrder = "featured";

      // 1. Saved Favorites in localStorage
      let savedFavorites = [];
      try {
        const storedFav = localStorage.getItem("car_rental_favorites");
        if (storedFav) savedFavorites = JSON.parse(storedFav);
      } catch(e) {}

      function updateWishlistHeartStates() {
        document.querySelectorAll(".card-wishlist-btn").forEach(btn => {
          const car = btn.dataset.car;
          if (savedFavorites.includes(car)) {
            btn.classList.add("active");
            btn.innerHTML = '<i class="ri-heart-fill"></i>';
          } else {
            btn.classList.remove("active");
            btn.innerHTML = '<i class="ri-heart-line"></i>';
          }
        });
      }

      document.addEventListener("click", (e) => {
        const favBtn = e.target.closest(".card-wishlist-btn");
        if (favBtn) {
          e.preventDefault();
          e.stopPropagation();
          const car = favBtn.dataset.car;
          if (savedFavorites.includes(car)) {
            savedFavorites = savedFavorites.filter(c => c !== car);
            showToast("Removed " + car + " from saved cars.", "info");
          } else {
            savedFavorites.push(car);
            showToast("Saved " + car + " to your favorites!", "success");
          }
          try {
            localStorage.setItem("car_rental_favorites", JSON.stringify(savedFavorites));
          } catch(e) {}
          updateWishlistHeartStates();
        }
      });

      // 2. Comprehensive Fleet Filter & Search
      function applyFleetFilters() {
        const allCards = document.querySelectorAll(".deals__card");
        let visibleCount = 0;

        allCards.forEach(card => {
          const carName = (card.dataset.car || card.querySelector("h4")?.innerText || "").toLowerCase();
          const brand = (card.dataset.brand || "").toLowerCase();
          const category = (card.dataset.category || "").toLowerCase();
          const query = activeSearchQuery.toLowerCase().trim();

          // Brand tab match
          let matchBrand = (activeBrandFilter === "All") || (card.dataset.brand === activeBrandFilter);
          
          // Category pill match
          let matchCat = (activeCategoryFilter === "all") || category.includes(activeCategoryFilter);

          // Query match
          let matchQuery = !query || carName.includes(query) || brand.includes(query) || category.includes(query);

          if (matchBrand && matchCat && matchQuery) {
            card.style.display = "";
            visibleCount++;
          } else {
            card.style.display = "none";
          }
        });

        // If All Brands is selected, ensure all tab containers are visible
        const tabContents = document.querySelectorAll(".tab__content");
        if (activeBrandFilter === "All") {
          tabContents.forEach(tab => {
            tab.style.display = "grid";
          });
        } else {
          tabContents.forEach(tab => {
            if (tab.id === activeBrandFilter) {
              tab.style.display = "grid";
            } else {
              tab.style.display = "none";
            }
          });
        }

        // Update counter
        const countNum = document.getElementById("fleet-count-num");
        if (countNum) countNum.innerText = visibleCount;
      }

      // Fleet Search Input Listeners
      const fleetSearchInput = document.getElementById("fleet-search-input");
      const fleetSearchClear = document.getElementById("fleet-search-clear");
      if (fleetSearchInput) {
        fleetSearchInput.addEventListener("input", (e) => {
          activeSearchQuery = e.target.value;
          if (fleetSearchClear) {
            fleetSearchClear.style.display = activeSearchQuery ? "flex" : "none";
          }
          applyFleetFilters();
        });
      }
      if (fleetSearchClear) {
        fleetSearchClear.addEventListener("click", () => {
          if (fleetSearchInput) fleetSearchInput.value = "";
          activeSearchQuery = "";
          fleetSearchClear.style.display = "none";
          applyFleetFilters();
        });
      }

      // Category Pills Listener
      const catPills = document.querySelectorAll(".cat-pill");
      catPills.forEach(pill => {
        pill.addEventListener("click", () => {
          catPills.forEach(p => p.classList.remove("active"));
          pill.classList.add("active");
          activeCategoryFilter = pill.dataset.category || "all";
          applyFleetFilters();
        });
      });

      // Tab Brand Switcher Overwrite
      const dealsTabs = document.querySelector(".deals__tabs");
      if (dealsTabs) {
        dealsTabs.addEventListener("click", (e) => {
          const btn = e.target.closest("button");
          if (!btn || !btn.dataset.id) return;
          dealsTabs.querySelectorAll("button").forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          activeBrandFilter = btn.dataset.id;
          applyFleetFilters();
        });
      }

      // Sort Select Listener
      const sortSelect = document.getElementById("fleet-sort-select");
      if (sortSelect) {
        sortSelect.addEventListener("change", (e) => {
          const val = e.target.value;
          const tabContents = document.querySelectorAll(".tab__content");
          tabContents.forEach(container => {
            const cards = Array.from(container.querySelectorAll(".deals__card"));
            cards.sort((a, b) => {
              const priceA = parseFloat(a.dataset.price || 0);
              const priceB = parseFloat(b.dataset.price || 0);
              if (val === "price-asc") return priceA - priceB;
              if (val === "price-desc") return priceB - priceA;
              return 0;
            });
            cards.forEach(card => container.appendChild(card));
          });
        });
      }

      // 3. Quick View Modal Controller
      const quickViewModal = document.getElementById("quick-view-modal");
      const closeQvBtn = document.getElementById("close-quick-view-btn");
      let currentViewingCar = null;

      function openQuickView(carName) {
        const spec = carSpecsMap[carName];
        if (!spec || !quickViewModal) return;
        currentViewingCar = carName;

        // Populate modal data
        document.getElementById("qv-car-badge").innerText = spec.badge || "Executive";
        document.getElementById("qv-car-brand").innerText = spec.brand;
        document.getElementById("qv-car-title").innerText = carName;
        document.getElementById("qv-car-price").innerHTML = "$" + spec.price + "<span> / 24 Hours</span>";
        document.getElementById("qv-spec-hp").innerText = spec.hp;
        document.getElementById("qv-spec-accel").innerText = spec.accel;
        document.getElementById("qv-spec-range").innerText = spec.range;
        document.getElementById("qv-spec-trans").innerText = spec.trans;
        document.getElementById("qv-spec-seats").innerText = spec.seats;
        document.getElementById("qv-spec-luggage").innerText = spec.luggage;

        // Image
        const cardImg = document.querySelector('.deals__card[data-car="' + carName + '"] img');
        const qvImg = document.getElementById("qv-car-img");
        if (cardImg && qvImg) {
          qvImg.src = cardImg.src;
        }

        // Features
        const featList = document.getElementById("qv-features-list");
        if (featList && spec.features) {
          featList.innerHTML = spec.features.map(f => '<li><i class="ri-checkbox-circle-fill"></i> ' + f + '</li>').join("");
        }

        quickViewModal.classList.add("active");
        document.body.style.overflow = "hidden";
      }

      function closeQuickView() {
        if (quickViewModal) quickViewModal.classList.remove("active");
        document.body.style.overflow = "";
      }

      if (closeQvBtn) closeQvBtn.addEventListener("click", closeQuickView);
      if (quickViewModal) {
        quickViewModal.addEventListener("click", (e) => {
          if (e.target === quickViewModal) closeQuickView();
        });
      }

      // 4. Grand Reservation & Checkout Modal Controller
      const resModal = document.getElementById("booking-reservation-modal");
      const closeResBtn = document.getElementById("close-reservation-btn");
      const resForm = document.getElementById("reservation-form");
      let currentBookingCar = null;
      let appliedPromoDiscount = 0;
      let appliedPromoCode = "";

      function openReservationModal(carName) {
        const spec = carSpecsMap[carName] || { price: 180, brand: "Premium" };
        currentBookingCar = carName;
        appliedPromoDiscount = 0;
        appliedPromoCode = "";

        if (quickViewModal) quickViewModal.classList.remove("active");

        // Set Car Header Preview
        document.getElementById("res-car-name").innerText = carName;
        document.getElementById("res-car-rate").innerText = "$" + spec.price;
        const cardImg = document.querySelector('.deals__card[data-car="' + carName + '"] img');
        const resThumb = document.getElementById("res-car-thumb");
        if (cardImg && resThumb) resThumb.src = cardImg.src;

        // Pre-fill location from Hero Search form or default
        const heroLoc = document.getElementById("location")?.value.trim();
        const pickLoc = document.getElementById("res-pickup-loc");
        const retLoc = document.getElementById("res-return-loc");
        if (pickLoc) pickLoc.value = heroLoc || "Hazrat Shahjalal Int'l Airport (DAC), Dhaka";
        if (retLoc) retLoc.value = heroLoc || "Hazrat Shahjalal Int'l Airport (DAC), Dhaka";

        // Pre-fill Dates: Defaults to tomorrow 10:00 AM to +3 days 10:00 AM
        const heroStart = document.getElementById("start")?.value;
        const heroStop = document.getElementById("stop")?.value;
        const startInput = document.getElementById("res-start-time");
        const stopInput = document.getElementById("res-return-time");

        const now = new Date();
        const defaultStart = new Date(now.getTime() + 24 * 3600 * 1000);
        defaultStart.setHours(10, 0, 0, 0);
        const defaultStop = new Date(defaultStart.getTime() + 3 * 24 * 3600 * 1000);

        const formatIsoLocal = (d) => {
          const tzOffset = d.getTimezoneOffset() * 60000;
          return (new Date(d.getTime() - tzOffset)).toISOString().slice(0, 16);
        };

        if (startInput) startInput.value = heroStart ? formatIsoLocal(new Date(heroStart)) : formatIsoLocal(defaultStart);
        if (stopInput) stopInput.value = heroStop ? formatIsoLocal(new Date(heroStop)) : formatIsoLocal(defaultStop);

        // Pre-fill Customer Info
        const nameInput = document.getElementById("res-cust-name");
        const phoneInput = document.getElementById("res-cust-phone");
        const emailInput = document.getElementById("res-cust-email");

        if (currentUser) {
          if (nameInput) nameInput.value = currentUser.name || "Asif Hasan";
          if (phoneInput) phoneInput.value = currentUser.phone || "+880 1618-956088";
          if (emailInput) emailInput.value = currentUser.email || "asifhasanarpon21@gmail.com";
        } else {
          if (nameInput && !nameInput.value) nameInput.value = "Guest Customer";
          if (phoneInput && !phoneInput.value) phoneInput.value = "+880 1618-956088";
          if (emailInput && !emailInput.value) emailInput.value = "customer@carrental.bd";
        }

        // Reset promo
        const promoInput = document.getElementById("res-promo-code");
        const promoMsg = document.getElementById("promo-status-msg");
        if (promoInput) promoInput.value = "";
        if (promoMsg) { promoMsg.innerText = ""; promoMsg.style.color = ""; }

        // Recalculate Live Bill
        recalculateLiveBill();

        resModal.classList.add("active");
        document.body.style.overflow = "hidden";
      }

      function closeReservationModal() {
        if (resModal) resModal.classList.remove("active");
        document.body.style.overflow = "";
      }

      if (closeResBtn) closeResBtn.addEventListener("click", closeReservationModal);
      if (resModal) {
        resModal.addEventListener("click", (e) => {
          if (e.target === resModal) closeReservationModal();
        });
      }

      function recalculateLiveBill() {
        const spec = carSpecsMap[currentBookingCar] || { price: 180 };
        const startVal = document.getElementById("res-start-time")?.value;
        const returnVal = document.getElementById("res-return-time")?.value;

        let days = 3;
        let hours = 72;
        if (startVal && returnVal) {
          const sDate = new Date(startVal);
          const rDate = new Date(returnVal);
          const diffMs = rDate - sDate;
          if (diffMs > 0) {
            hours = Math.round(diffMs / (1000 * 60 * 60));
            days = Math.max(1, Math.ceil(hours / 24));
          }
        }

        // Duration badges
        const daysBadge = document.getElementById("res-duration-days");
        const hoursBadge = document.getElementById("res-duration-hours");
        if (daysBadge) daysBadge.innerText = days + (days === 1 ? " Day" : " Days");
        if (hoursBadge) hoursBadge.innerText = hours + " Hours";

        // Daily Vehicle Subtotal
        const vehicleSub = spec.price * days;
        document.getElementById("inv-days-count").innerText = days;
        document.getElementById("inv-day-rate").innerText = spec.price;
        document.getElementById("inv-vehicle-sub").innerText = "$" + vehicleSub;

        // Driver option
        const driverChoice = document.querySelector('input[name="res-driver-choice"]:checked')?.value;
        const driverRow = document.getElementById("inv-driver-row");
        let driverFee = 0;
        if (driverChoice === "chauffeur") {
          driverFee = 25 * days;
          if (driverRow) {
            driverRow.style.display = "flex";
            document.getElementById("inv-driver-sub").innerText = "+$" + driverFee;
          }
        } else {
          if (driverRow) driverRow.style.display = "none";
        }

        // Protection option
        const protectChoice = document.querySelector('input[name="res-protect-choice"]:checked')?.value;
        const protectRow = document.getElementById("inv-protect-row");
        let protectFee = 0;
        if (protectChoice === "premium") {
          protectFee = 15 * days;
          if (protectRow) {
            protectRow.style.display = "flex";
            document.getElementById("inv-protect-sub").innerText = "+$" + protectFee;
          }
        } else {
          if (protectRow) protectRow.style.display = "none";
        }

        // Subtotal before tax and discount
        let subtotal = vehicleSub + driverFee + protectFee;

        // Promo Discount
        const discountRow = document.getElementById("inv-discount-row");
        let discountAmount = 0;
        if (appliedPromoDiscount > 0) {
          discountAmount = Math.round(subtotal * appliedPromoDiscount);
          if (discountRow) {
            discountRow.style.display = "flex";
            document.getElementById("inv-promo-label").innerText = appliedPromoCode;
            document.getElementById("inv-discount-sub").innerText = "-$" + discountAmount;
          }
        } else {
          if (discountRow) discountRow.style.display = "none";
        }

        // Tax 5%
        const taxable = Math.max(0, subtotal - discountAmount);
        const tax = Math.round(taxable * 0.05);
        document.getElementById("inv-tax-sub").innerText = "$" + tax;

        // Final Total
        const finalTotal = taxable + tax;
        document.getElementById("inv-total-final").innerText = "$" + finalTotal;
        return { days, hours, vehicleSub, driverFee, protectFee, discountAmount, tax, finalTotal };
      }

      // Input changes trigger recalculateLiveBill
      ["res-start-time", "res-return-time"].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener("change", recalculateLiveBill);
      });
      document.querySelectorAll('input[name="res-driver-choice"], input[name="res-protect-choice"]').forEach(el => {
        el.addEventListener("change", recalculateLiveBill);
      });

      // Promo Code Apply Button
      const applyPromoBtn = document.getElementById("apply-promo-btn");
      if (applyPromoBtn) {
        applyPromoBtn.addEventListener("click", () => {
          const codeInput = document.getElementById("res-promo-code");
          const msgEl = document.getElementById("promo-status-msg");
          const code = (codeInput?.value || "").toUpperCase().trim();
          if (code === "VIP10") {
            appliedPromoDiscount = 0.10;
            appliedPromoCode = "10% VIP DISCOUNT";
            if (msgEl) { msgEl.innerText = "✓ VIP10 applied: 10% discount!"; msgEl.style.color = "#10b981"; }
          } else if (code === "RENTBD") {
            appliedPromoDiscount = 0.15;
            appliedPromoCode = "15% SPECIAL DISCOUNT";
            if (msgEl) { msgEl.innerText = "✓ RENTBD applied: 15% discount!"; msgEl.style.color = "#10b981"; }
          } else if (code === "WELCOME") {
            appliedPromoDiscount = 0.05;
            appliedPromoCode = "5% WELCOME OFFER";
            if (msgEl) { msgEl.innerText = "✓ WELCOME applied: 5% discount!"; msgEl.style.color = "#10b981"; }
          } else {
            appliedPromoDiscount = 0;
            appliedPromoCode = "";
            if (msgEl) { msgEl.innerText = "✗ Invalid promo code. Try VIP10 or RENTBD"; msgEl.style.color = "#ef4444"; }
          }
          recalculateLiveBill();
        });
      }

      // 5. Booking Confirmation & Official Voucher Receipt
      const voucherModal = document.getElementById("booking-voucher-modal");
      const closeVoucherBtn = document.getElementById("close-voucher-btn");
      const voucherPrintBtn = document.getElementById("voucher-print-btn");
      const voucherDashBtn = document.getElementById("voucher-dash-btn");

      if (closeVoucherBtn) {
        closeVoucherBtn.addEventListener("click", () => {
          if (voucherModal) voucherModal.classList.remove("active");
          document.body.style.overflow = "";
        });
      }
      if (voucherPrintBtn) {
        voucherPrintBtn.addEventListener("click", () => {
          window.print();
        });
      }
      if (voucherDashBtn) {
        voucherDashBtn.addEventListener("click", () => {
          if (voucherModal) voucherModal.classList.remove("active");
          document.body.style.overflow = "";
          openDashboard("bookings");
        });
      }

      if (resForm) {
        resForm.addEventListener("submit", async (e) => {
          e.preventDefault();
          const submitBtn = document.getElementById("res-submit-btn");
          const originalBtnHtml = submitBtn.innerHTML;
          submitBtn.innerHTML = '<span>Processing Secure Reservation...</span> <i class="ri-loader-4-line ri-spin"></i>';
          submitBtn.disabled = true;

          const bill = recalculateLiveBill();
          const pickupLoc = document.getElementById("res-pickup-loc").value;
          const returnLoc = document.getElementById("res-return-loc").value;
          const startTime = document.getElementById("res-start-time").value;
          const returnTime = document.getElementById("res-return-time").value;
          const custName = document.getElementById("res-cust-name").value;
          const custPhone = document.getElementById("res-cust-phone").value;
          const custEmail = document.getElementById("res-cust-email").value;

          const refCode = "CR-" + new Date().getFullYear() + "-" + Math.floor(10000 + Math.random() * 90000);
          const driverPhone = "+880 1712-345678";

          // Save to userBookings
          const newBooking = {
            id: Date.now(),
            ref_code: refCode,
            car_name: currentBookingCar,
            pickup_location: pickupLoc,
            return_location: returnLoc,
            start_time: startTime,
            return_time: returnTime,
            name: custName,
            email: custEmail,
            phone: custPhone,
            total_amount: bill.finalTotal,
            driver_phone: driverPhone,
            status: "confirmed",
            created_at: new Date().toISOString()
          };
          userBookings.unshift(newBooking);
          try {
            localStorage.setItem("car_rental_bookings", JSON.stringify(userBookings));
          } catch(e) {}

          // Attempt sync with backend
          try {
            await fetch('/bookings', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-CSRF-TOKEN': csrfToken
              },
              body: JSON.stringify({
                car_name: currentBookingCar,
                pickup_location: pickupLoc,
                start_time: startTime,
                return_time: returnTime,
                email: custEmail,
                phone: custPhone,
                total: bill.finalTotal
              })
            });
          } catch(err) {}

          // Update Dashboard UI counters immediately
          updateDashboardUI();

          setTimeout(() => {
            submitBtn.innerHTML = originalBtnHtml;
            submitBtn.disabled = false;
            closeReservationModal();

            // Populate Voucher
            document.getElementById("voucher-ref-id").innerText = "#" + refCode;
            document.getElementById("voucher-issued-date").innerText = "Issued: " + new Date().toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
            document.getElementById("voucher-car-name").innerText = currentBookingCar;
            const spec = carSpecsMap[currentBookingCar] || {};
            document.getElementById("voucher-car-cat").innerText = spec.badge || "Executive Luxury";
            
            const cardImg = document.querySelector('.deals__card[data-car="' + currentBookingCar + '"] img');
            const vImg = document.getElementById("voucher-car-img");
            if (cardImg && vImg) vImg.src = cardImg.src;

            document.getElementById("voucher-pickup-loc").innerText = pickupLoc;
            document.getElementById("voucher-pickup-time").innerText = formatDateTime(startTime);
            document.getElementById("voucher-return-loc").innerText = returnLoc;
            document.getElementById("voucher-return-time").innerText = formatDateTime(returnTime);
            document.getElementById("voucher-cust-name").innerText = custName;
            document.getElementById("voucher-cust-phone").innerText = custPhone;
            document.getElementById("voucher-duration-str").innerText = bill.days + " Days (" + bill.hours + " Hours)";
            document.getElementById("voucher-rate-str").innerText = "$" + spec.price + " / Day";
            document.getElementById("voucher-total-paid").innerText = "$" + bill.finalTotal + " USD";

            voucherModal.classList.add("active");
            showToast("Reservation #" + refCode + " Confirmed!", "success");
          }, 800);
        });
      }

      // Delegate clicks for Specs and Rent buttons across all cards
      document.addEventListener("click", (e) => {
        const specsBtn = e.target.closest(".btn-card-specs");
        if (specsBtn) {
          e.preventDefault();
          const car = specsBtn.dataset.car;
          openQuickView(car);
          return;
        }

        const rentBtn = e.target.closest(".btn-card-rent");
        if (rentBtn) {
          e.preventDefault();
          const car = rentBtn.dataset.car;
          openReservationModal(car);
          return;
        }

        const qvBookBtn = e.target.closest("#qv-book-now-btn");
        if (qvBookBtn && currentViewingCar) {
          e.preventDefault();
          openReservationModal(currentViewingCar);
          return;
        }
      });

      // 6. Guest Explore Button Handler
      const guestExploreBtn = document.getElementById("guest-explore-btn");
      if (guestExploreBtn) {
        guestExploreBtn.addEventListener("click", () => {
          authOverlay.style.opacity = '0';
          authOverlay.style.visibility = 'hidden';
          authOverlay.style.pointerEvents = 'none';
          document.body.classList.remove('locked-screen');
          renderUserProfile('Guest Visitor', 'guest@carrental.bd', '+880 1618-956088');
          initScrollReveal();
          showToast("Browsing as Guest. Welcome to CarRental BD!", "success");
        });
      }

      // 7. Floating Back to Top & Hotline
      const backToTopBtn = document.getElementById("back-to-top-btn");
      window.addEventListener("scroll", () => {
        if (window.scrollY > 350) {
          if (backToTopBtn) backToTopBtn.classList.add("show");
        } else {
          if (backToTopBtn) backToTopBtn.classList.remove("show");
        }
      });
      if (backToTopBtn) {
        backToTopBtn.addEventListener("click", () => {
          window.scrollTo({ top: 0, behavior: "smooth" });
        });
      }

      // Initialize Fleet Filters & Wishlist States on load
      setTimeout(() => {
        updateWishlistHeartStates();
        applyFleetFilters();
      }, 100);

      
      // ==========================================================
      // CANCELLATION ENGINE CONTROLLER
      // ==========================================================
      let pendingCancelBookingId = null;
      const cancelModal = document.getElementById("cancel-confirm-modal");
      const closeCancelBtn = document.getElementById("close-cancel-modal-btn");
      const dismissCancelBtn = document.getElementById("dismiss-cancel-btn");
      const confirmCancelBtn = document.getElementById("confirm-cancel-btn");

      function triggerCancelBooking(bookingId) {
        pendingCancelBookingId = bookingId;
        const booking = userBookings.find(b => String(b.id) === String(bookingId) || String(b.ref_code) === String(bookingId));
        if (!booking) return;

        const carEl = document.getElementById("cancel-modal-car");
        const refEl = document.getElementById("cancel-modal-ref");
        const refCode = booking.ref_code || ("CR-2026-" + (90000 + (booking.id % 9000)));

        if (carEl) carEl.innerText = booking.car_name;
        if (refEl) refEl.innerText = "Booking Ref: #" + refCode;

        if (cancelModal) {
          cancelModal.classList.add("active");
          document.body.style.overflow = "hidden";
        }
      }

      function closeCancelModal() {
        if (cancelModal) cancelModal.classList.remove("active");
        document.body.style.overflow = "";
        pendingCancelBookingId = null;
      }

      if (closeCancelBtn) closeCancelBtn.addEventListener("click", closeCancelModal);
      if (dismissCancelBtn) dismissCancelBtn.addEventListener("click", closeCancelModal);
      if (cancelModal) {
        cancelModal.addEventListener("click", (e) => {
          if (e.target === cancelModal) closeCancelModal();
        });
      }

      if (confirmCancelBtn) {
        confirmCancelBtn.addEventListener("click", async () => {
          if (!pendingCancelBookingId) return;
          const booking = userBookings.find(b => String(b.id) === String(pendingCancelBookingId) || String(b.ref_code) === String(pendingCancelBookingId));
          if (!booking) return;

          booking.status = "cancelled";
          try {
            localStorage.setItem("car_rental_bookings", JSON.stringify(userBookings));
          } catch(e) {}

          // Attempt sync with backend
          try {
            await fetch('/bookings/' + booking.id, {
              method: 'DELETE',
              headers: { 'X-CSRF-TOKEN': csrfToken, 'Accept': 'application/json' }
            });
          } catch(e) {}

          // Update Dashboard UI
          updateDashboardUI();

          // If voucher is open, update voucher status
          const voucherBadge = document.querySelector(".voucher-badge-top");
          if (voucherBadge) {
            voucherBadge.innerHTML = '<i class="ri-close-circle-fill"></i> Booking Cancelled & Refunded';
            voucherBadge.style.background = '#fee2e2';
            voucherBadge.style.borderColor = '#fca5a5';
            voucherBadge.style.color = '#991b1b';
          }

          closeCancelModal();
          showToast("Rental for " + booking.car_name + " was successfully cancelled.", "error");
        });
      }

      // Voucher Cancel Button Listener
      const voucherCancelBtn = document.getElementById("voucher-cancel-btn");
      if (voucherCancelBtn) {
        voucherCancelBtn.addEventListener("click", () => {
          const refCode = document.getElementById("voucher-ref-id")?.innerText.replace('#', '').trim();
          const booking = userBookings.find(b => b.ref_code === refCode || String(b.id) === refCode);
          if (booking) {
            triggerCancelBooking(booking.id);
          } else if (userBookings.length > 0) {
            triggerCancelBooking(userBookings[0].id);
          }
        });
      }

      // View Voucher helper from Dashboard
      function viewVoucherForBooking(bookingId) {
        const b = userBookings.find(x => String(x.id) === String(bookingId) || String(x.ref_code) === String(bookingId));
        if (!b) return;

        const vModal = document.getElementById("booking-voucher-modal");
        const refCode = b.ref_code || ("CR-2026-" + (90000 + (b.id % 9000)));

        document.getElementById("voucher-ref-id").innerText = "#" + refCode;
        document.getElementById("voucher-issued-date").innerText = "Issued: " + new Date(b.created_at || Date.now()).toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
        document.getElementById("voucher-car-name").innerText = b.car_name;
        
        const spec = carSpecsMap[b.car_name] || {};
        document.getElementById("voucher-car-cat").innerText = spec.badge || "Executive Luxury";

        const carImg = getCarImage(b.car_name);
        const vImg = document.getElementById("voucher-car-img");
        if (vImg) vImg.src = carImg;

        document.getElementById("voucher-pickup-loc").innerText = b.pickup_location || "Hazrat Shahjalal Int'l Airport";
        document.getElementById("voucher-pickup-time").innerText = formatDateTime(b.start_time);
        document.getElementById("voucher-return-loc").innerText = b.return_location || b.pickup_location || "Hazrat Shahjalal Int'l Airport";
        document.getElementById("voucher-return-time").innerText = formatDateTime(b.return_time);
        document.getElementById("voucher-cust-name").innerText = b.name || "Customer";
        document.getElementById("voucher-cust-phone").innerText = b.phone || "+880 1618-956088";
        document.getElementById("voucher-duration-str").innerText = "3 Days (72 Hours)";
        document.getElementById("voucher-rate-str").innerText = "$" + (spec.price || 180) + " / Day";
        document.getElementById("voucher-total-paid").innerText = "$" + (b.total_amount || 567) + " USD";

        const voucherBadge = document.querySelector(".voucher-badge-top");
        if (voucherBadge) {
          if (b.status === "cancelled") {
            voucherBadge.innerHTML = '<i class="ri-close-circle-fill"></i> Booking Cancelled & Refunded';
            voucherBadge.style.background = '#fee2e2';
            voucherBadge.style.borderColor = '#fca5a5';
            voucherBadge.style.color = '#991b1b';
          } else {
            voucherBadge.innerHTML = '<i class="ri-checkbox-circle-fill"></i> Booking Confirmed & Guaranteed';
            voucherBadge.style.background = '#ecfdf5';
            voucherBadge.style.borderColor = '#a7f3d0';
            voucherBadge.style.color = '#065f46';
          }
        }

        closeDashboard();
        if (vModal) {
          vModal.classList.add("active");
          document.body.style.overflow = "hidden";
        }
      }

      // Rent Now Button Immediate Toast Notification & Modal Trigger
      document.addEventListener("click", (e) => {
        const rentBtn = e.target.closest(".btn-card-rent");
        if (rentBtn) {
          e.preventDefault();
          e.stopPropagation();
          const card = rentBtn.closest(".deals__card");
          const car = rentBtn.dataset.car || (card ? card.dataset.car : "") || card.querySelector("h4")?.innerText;
          showToast("Selected " + car + "! Opening reservation...", "info");
          openReservationModal(car);
        }
      });

      function initScrollReveal() {
        const scrollRevealOption = {
          distance: "40px",
          origin: "bottom",
          duration: 900,
        };

        ScrollReveal().reveal(".header__image", { ...scrollRevealOption, origin: "right" });
        ScrollReveal().reveal(".hero-pill-badge", { ...scrollRevealOption, delay: 150 });
        ScrollReveal().reveal(".hero-title", { ...scrollRevealOption, delay: 300 });
        ScrollReveal().reveal(".hero-description", { ...scrollRevealOption, delay: 450 });
        ScrollReveal().reveal(".hero-action-btns", { ...scrollRevealOption, delay: 600 });
        ScrollReveal().reveal(".hero-trust-metrics", { ...scrollRevealOption, delay: 750 });
        ScrollReveal().reveal(".header__form form", { ...scrollRevealOption, delay: 900 });
        ScrollReveal().reveal(".about__card", { ...scrollRevealOption, interval: 250 });
        ScrollReveal().reveal(".choose__image img", { ...scrollRevealOption, origin: "left" });
        ScrollReveal().reveal(".choose__content .section__header", { ...scrollRevealOption, delay: 300 });
        ScrollReveal().reveal(".choose__content .section__description", { ...scrollRevealOption, delay: 500 });
        ScrollReveal().reveal(".choose__card", { duration: 900, delay: 600, interval: 250 });
        ScrollReveal().reveal(".subscribe__image img", { ...scrollRevealOption, origin: "right" });
        ScrollReveal().reveal(".subscribe__content .section__header", { ...scrollRevealOption, delay: 300 });
        ScrollReveal().reveal(".subscribe__content .section__description", { ...scrollRevealOption, delay: 500 });
        ScrollReveal().reveal(".subscribe__content form", { ...scrollRevealOption, delay: 700 });
      }
    </script>
  </body>
</html>